"use client";

import { motion } from "motion/react";

export function ElasticPressButtonTailwind({ label = "Commit Production Release" }) {
  return (
    <motion.button
      type="button"
      whileHover={{ scale: 1.03 }}
      whileTap={{ scaleX: 1.04, scaleY: 0.91 }}
      transition={{ type: "spring", stiffness: 380, damping: 14 }}
      className="rounded-lg border border-zinc-700 bg-zinc-900 px-5 py-2.5 text-sm font-medium text-zinc-100 shadow-inner"
    >
      {label}
    </motion.button>
  );
}
